        if (test != null && test.length() > 0) {

            String wi_contents = contents.replaceAll("[ \\\t]+", " ");
            String wi_test = test.replaceAll("[ \\\t]+", " ");
            // Convert Windows CRLF to UNIX LF
            wi_contents = wi_contents.replaceAll("\\\r\\\n", "\n");
